import mw_tool,numpy as np
s=mw_tool.Session('/app/instance.npz');o=s.state()['object_pos']
def move(target,dwell):
 for _ in range(100):
  d=np.array(target)-s.state()['mocap_pos']
  if np.max(abs(d))<.002:break
  s.step(np.r_[np.clip(d/.01,-1,1),-1])
 for _ in range(dwell):s.step([0,0,0,-1])
for start in [18,20,22,24,26,28,30]:
 for dx in [0.1,0.2,0.35,0.5,0.7,1.0]:
  s.reset();move([o[0],o[1]+.095,.2],30);move([o[0],o[1]+.095,.055],30)
  best=(1,None,None,None)
  for i in range(50):
   s.step([dx if i>=start else 0,-1,0,-1])
   d=s.check()['obj_to_target']
   if d<best[0]:best=(d,i+1,s.state()['object_pos'].copy(),s.state()['tcp'].copy())
  print(start,dx,'best',round(best[0],4),'step',best[1],'obj',np.round(best[2][:2],3),'tcp',np.round(best[3][:2],3))
